for(const id of ['escuela','corral','rancho'])fetch(`${base}scenes/${id}.json`,{method:'HEAD'}).then(r=>{if(r.ok&&!(r.headers.get('content-type')||'').includes('text/html'))scenes.add(id);}).catch(()=>{});
