function voiceFor(lineIndex){
 const lines=CHAPTERS[chapter].dialogue,speaker=lines[lineIndex].speaker,clips=voices.filter(v=>v.speaker===speaker);if(!clips.length)return null;
 const ordinal=lines.slice(0,lineIndex).filter(line=>line.speaker===speaker).length; // primera, segunda… vez que habla en este encuentro
 if(ordinal>=clips.length)return null; // sin repetir un fragmento dentro del mismo encuentro
 return clips[(ordinal+(chapter===5?1:0))%clips.length];
}
